const API_BASEURL = "http://127.0.0.1:8000/api";

const API_ENDPOINTS = {
    texts: `${API_BASEURL}/text`,
    images: `${API_BASEURL}/images`,
    buttons: `${API_BASEURL}/button`,
    addons: `${API_BASEURL}/addon`
};

export {API_BASEURL, API_ENDPOINTS};
